mapper.select:
SELECT FROM cps_dict_type WHERE 1 = 1
AND enabled = #{enabled}
ORDER BY sort_no ASC, type_code ASC, id ASC

mapper.insert:
INSERT INTO cps_dict_type (
    type_code, type_name, description, builtin, enabled, sort_no,
    created_by, updated_by
) VALUES (
    #{typeCode}, #{typeName}, #{description}, #{builtin}, #{enabled}, #{sortNo},
    #{createdBy}, #{updatedBy}
)

mapper.update:
UPDATE cps_dict_type
SET type_name = #{typeName},
    description = #{description},
    sort_no = #{sortNo},
    updated_by = #{updatedBy}
WHERE id = #{id}

UPDATE cps_dict_type
SET enabled = #{enabled}, updated_by = #{updatedBy}
WHERE id = #{id}
